public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        double[] X = new double[N], Y = new double[N];
        for (int i = 0; i < N; i++) { X[i] = sc.nextDouble(); Y[i] = sc.nextDouble(); }

        double[] hx = new double[N+1], hy = new double[N+1];
        for (int i = 0; i < N; i++) { hx[i] = X[i]; hy[i] = Y[i]; }
        hx[N] = 0; hy[N] = 0;

        double[][][] dp = new double[1<<N][N][N+1];
        for (double[][] a : dp) for (double[] b : a) Arrays.fill(b, Double.MAX_VALUE/2);

        double angle = Math.atan2(0,1); // initial facing (1,0)
        for (int i = 0; i < N; i++) {
            double dir = Math.atan2(hy[i]-0, hx[i]-0);
            double turn = Math.abs(angleDiff(dir, angle));
            dp[1<<i][i][N] = turn;
        }

        for (int mask = 1; mask < (1<<N); mask++) {
            for (int i = 0; i < N; i++) {
                if ((mask & (1<<i)) == 0) continue;
                for (int prev = 0; prev <= N; prev++) {
                    if (dp[mask][i][prev] >= Double.MAX_VALUE/2) continue;
                    double arrDir = Math.atan2(hy[i]-hy[prev], hx[i]-hx[prev]);
                    for (int j = 0; j < N; j++) {
                        if ((mask & (1<<j)) != 0) continue;
                        double depDir = Math.atan2(hy[j]-hy[i], hx[j]-hx[i]);
                        double turn = Math.abs(angleDiff(depDir, arrDir));
                        int nmask = mask | (1<<j);
                        if (dp[nmask][j][i] > dp[mask][i][prev] + turn)
                            dp[nmask][j][i] = dp[mask][i][prev] + turn;
                    }
                }
            }
        }

        int full = (1<<N)-1;
        double ans = Double.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            for (int prev = 0; prev <= N; prev++) {
                if (dp[full][i][prev] >= Double.MAX_VALUE/2) continue;
                double arrDir = Math.atan2(hy[i]-hy[prev], hx[i]-hx[prev]);
                double homeDir = Math.atan2(0-hy[i], 0-hx[i]);
                double turn = Math.abs(angleDiff(homeDir, arrDir));
                ans = Math.min(ans, dp[full][i][prev] + turn);
            }
        }

        System.out.printf("%.10f%n", ans * 180 / Math.PI);
    }

    static double angleDiff(double a, double b) {
        double d = a - b;
        while (d > Math.PI) d -= 2*Math.PI;
        while (d < -Math.PI) d += 2*Math.PI;
        return d;
    }
}

