public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        double ang;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
            this.ang = Math.atan2(y, x);
            if (this.ang < 0) this.ang += 2.0 * Math.PI;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        Point[] p = new Point[N];
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            p[i] = new Point(x, y);
        }

        // Sort by polar angle around origin.
        Arrays.sort(p, Comparator.comparingDouble(a -> a.ang));

        // If all stores lie on one ray from the origin, answer is 0.
        boolean allSame = true;
        for (int i = 1; i < N; i++) {
            if (Math.abs(p[i].ang - p[0].ang) > 1e-15) {
                allSame = false;
                break;
            }
        }
        if (allSame) {
            System.out.println("0.0");
            return;
        }

        // Key fact:
        // An optimal route corresponds to visiting stores in circular order around the origin,
        // with exactly one "gap" skipped. Total rotation equals 2*pi - largest angular gap.
        double maxGap = 0.0;
        for (int i = 0; i < N; i++) {
            double a1 = p[i].ang;
            double a2 = p[(i + 1) % N].ang;
            double gap = a2 - a1;
            if (gap < 0) gap += 2.0 * Math.PI;
            if (i == N - 1) gap = p[0].ang + 2.0 * Math.PI - p[i].ang;
            maxGap = Math.max(maxGap, gap);
        }

        double ans = 2.0 * Math.PI - maxGap;
        System.out.printf(Locale.US, "%.15f%n", ans);
    }
}

