using namespace std;

static const double INF = 1e100;
static const double PI = acos(-1.0);
static const double EPS = 1e-12;

double norm_angle(double a) {
    while (a < 0) a += 2.0 * PI;
    while (a >= 2.0 * PI) a -= 2.0 * PI;
    return a;
}

double ang_diff(double a, double b) {
    double d = fabs(a - b);
    return min(d, 2.0 * PI - d);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<double> x(N + 1), y(N + 1);
    x[0] = 0.0; y[0] = 0.0;
    for (int i = 1; i <= N; i++) cin >> x[i] >> y[i];

    // Precompute directions between every pair of distinct points.
    vector<vector<double>> dir(N + 1, vector<double>(N + 1, 0.0));
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            if (i == j) continue;
            dir[i][j] = norm_angle(atan2(y[j] - y[i], x[j] - x[i]));
        }
    }

    int FULL = 1 << N;

    // dp[mask][i][k]:
    // visited stores = mask
    // currently at point i (0..N, where 0 is home, i>0 means store i)
    // last movement direction index k:
    //   k = 0 means initial direction (1,0), angle 0
    //   k = j (1..N, j != i) means the last segment came from point j to i,
    //       so current facing direction is dir[j][i]
    //
    // This state is enough because turning cost at current point depends only on
    // current facing direction and chosen next segment.
    vector<vector<vector<double>>> dp(
        FULL, vector<vector<double>>(N + 1, vector<double>(N + 1, INF))
    );

    dp[0][0][0] = 0.0;

    for (int mask = 0; mask < FULL; mask++) {
        for (int i = 0; i <= N; i++) {
            for (int k = 0; k <= N; k++) {
                double cur = dp[mask][i][k];
                if (cur >= INF / 2) continue;

                double face;
                if (k == 0) {
                    // Only valid at home before any move.
                    if (!(i == 0 && mask == 0)) continue;
                    face = 0.0;
                } else {
                    if (k == i) continue;
                    face = dir[k][i];
                }

                // Go to an unvisited store.
                for (int s = 1; s <= N; s++) {
                    if (mask & (1 << (s - 1))) continue;
                    if (s == i) continue;

                    double need = dir[i][s];
                    double add = ang_diff(face, need);
                    int nmask = mask | (1 << (s - 1));
                    dp[nmask][s][i] = min(dp[nmask][s][i], cur + add);
                }

                // If all stores visited, can return home.
                if (mask == FULL - 1 && i != 0) {
                    double need = dir[i][0];
                    double add = ang_diff(face, need);
                    dp[mask][0][i] = min(dp[mask][0][i], cur + add);
                }
            }
        }
    }

    double ans = INF;

    // Need to end at home. After arriving home, he may rotate there freely,
    // so to match the initial facing direction (1,0), add that final rotation.
    for (int k = 1; k <= N; k++) {
        double cur = dp[FULL - 1][0][k];
        if (cur >= INF / 2) continue;
        double face = dir[k][0];
        ans = min(ans, cur + ang_diff(face, 0.0));
    }

    cout << fixed << setprecision(15) << ans * 180.0 / PI << '\n';
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_N 15
#define INF 1e9

typedef struct {
    double x, y;
} Point;

int n;
Point stores[MAX_N];
double dist[MAX_N][MAX_N];
double dp[1 << MAX_N][MAX_N];

double angle_between(Point a, Point b, Point c) {
    // angle between vectors ab and bc
    double v1x = b.x - a.x;
    double v1y = b.y - a.y;
    double v2x = c.x - b.x;
    double v2y = c.y - b.y;

    double dot = v1x * v2x + v1y * v2y;
    double norm1 = sqrt(v1x * v1x + v1y * v1y);
    double norm2 = sqrt(v2x * v2x + v2y * v2y);

    if (norm1 < 1e-12 || norm2 < 1e-12) return 0.0;

    double cos_theta = dot / (norm1 * norm2);
    if (cos_theta > 1.0) cos_theta = 1.0;
    if (cos_theta < -1.0) cos_theta = -1.0;

    return acos(cos_theta);
}

double solve() {
    // dp[mask][last] = min rotation to visit stores in mask ending at store last
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++) {
            dp[mask][i] = INF;
        }
    }

    // Starting from home (0,0) facing (1,0)
    Point home = {0, 0};
    Point dir_vec = {1, 0}; // initial direction

    // Initialize: first store visited
    for (int i = 0; i < n; i++) {
        // angle from home to store i
        Point to_store = {stores[i].x - home.x, stores[i].y - home.y};
        double norm = sqrt(to_store.x * to_store.x + to_store.y * to_store.y);
        if (norm < 1e-12) {
            dp[1 << i][i] = 0.0;
        } else {
            double dot = dir_vec.x * to_store.x + dir_vec.y * to_store.y;
            double cos_theta = dot / norm;
            if (cos_theta > 1.0) cos_theta = 1.0;
            if (cos_theta < -1.0) cos_theta = -1.0;
            dp[1 << i][i] = acos(cos_theta);
        }
    }

    // DP over masks
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if (!(mask & (1 << last))) continue;
            if (dp[mask][last] >= INF/2) continue;

            for (int next = 0; next < n; next++) {
                if (mask & (1 << next)) continue;

                double angle = angle_between(stores[last], stores[last], stores[next]);
                // Actually we need angle between direction from previous to last and from last to next
                // But direction at last is from previous to last, so we need previous point
                // We'll compute it differently - need to know the previous point
                // Let's store the path differently
            }
        }
    }

    // Alternative approach: Since N <= 15, we can brute force permutations
    // For each permutation, compute total rotation
    int indices[MAX_N];
    for (int i = 0; i < n; i++) indices[i] = i;

    double min_angle = INF;

    do {
        // Start from home
        Point prev = home;
        Point dir = dir_vec;
        double total_angle = 0.0;

        for (int i = 0; i < n; i++) {
            int idx = indices[i];
            Point cur = stores[idx];

            // vector from prev to cur
            double vx = cur.x - prev.x;
            double vy = cur.y - prev.y;
            double norm = sqrt(vx * vx + vy * vy);

            if (norm > 1e-12) {
                double dot = dir.x * vx + dir.y * vy;
                double cos_theta = dot / norm;
                if (cos_theta > 1.0) cos_theta = 1.0;
                if (cos_theta < -1.0) cos_theta = -1.0;
                total_angle += acos(cos_theta);

                // update direction
                dir.x = vx / norm;
                dir.y = vy / norm;
            }
            prev = cur;
        }

        // Return to home
        double vx = home.x - prev.x;
        double vy = home.y - prev.y;
        double norm = sqrt(vx * vx + vy * vy);
        if (norm > 1e-12) {
            double dot = dir.x * vx + dir.y * vy;
            double cos_theta = dot / norm;
            if (cos_theta > 1.0) cos_theta = 1.0;
            if (cos_theta < -1.0) cos_theta = -1.0;
            total_angle += acos(cos_theta);
        }

        if (total_angle < min_angle) min_angle = total_angle;

    } while (next_permutation(indices, indices + n));

    return min_angle;
}

int next_permutation(int *first, int *last) {
    if (first == last) return 0;
    int *i = last - 1;
    while (i > first) {
        if (*(i-1) < *i) break;
        i--;
    }
    if (i == first) return 0;
    int *j = last - 1;
    while (*j <= *(i-1)) j--;
    int temp = *(i-1);
    *(i-1) = *j;
    *j = temp;
    // reverse suffix
    int *left = i, *right = last - 1;
    while (left < right) {
        temp = *left;
        *left = *right;
        *right = temp;
        left++;
        right--;
    }
    return 1;
}

