#include <math.h>

#define INF 1e100

typedef struct {
    double x, y;
} Point;

static double dist_angle(double a, double b) {
    double d = fabs(a - b);
    while (d >= 2.0 * M_PI) d -= 2.0 * M_PI;
    if (d > M_PI) d = 2.0 * M_PI - d;
    return d;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = N + 1;                 // 0 = home, 1..N = stores
    Point *p = (Point *)malloc(sizeof(Point) * M);
    p[0].x = 0.0; p[0].y = 0.0;
    for (int i = 1; i <= N; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    if (N == 0) {
        printf("0.10f\n", 0.0);
        free(p);
        return 0;
    }

    // angle[i][j] = direction angle from i to j
    double **ang = (double **)malloc(sizeof(double *) * M);
    for (int i = 0; i < M; i++) {
        ang[i] = (double *)malloc(sizeof(double) * M);
        for (int j = 0; j < M; j++) ang[i][j] = 0.0;
    }

    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
            if (i == j) continue;
            ang[i][j] = atan2(p[j].y - p[i].y, p[j].x - p[i].x);
        }
    }

    int S = 1 << N;
    double **dp = (double **)malloc(sizeof(double *) * S);
    for (int s = 0; s < S; s++) {
        dp[s] = (double *)malloc(sizeof(double) * N);
        for (int i = 0; i < N; i++) dp[s][i] = INF;
    }

    // First move: from home facing angle 0
    for (int i = 0; i < N; i++) {
        int ni = i + 1;
        dp[1 << i][i] = dist_angle(0.0, ang[0][ni]);
    }

    for (int mask = 0; mask < S; mask++) {
        for (int last = 0; last < N; last++) {
            if (!(mask & (1 << last))) continue;
            double cur = dp[mask][last];
            if (cur >= INF / 2) continue;

            int lastNode = last + 1;

            for (int nxt = 0; nxt < N; nxt++) {
                if (mask & (1 << nxt)) continue;
                int nxtNode = nxt + 1;
                double add = dist_angle(ang[lastNode][0], ang[lastNode][nxtNode]);
                // Wait: current facing at lastNode is direction from previous node to lastNode,
                // not from lastNode to 0. We need transition based on incoming direction.
                // To fix this, we reinterpret DP below with predecessor-aware optimization impossible.
                // So this simple DP is insufficient.
            }
        }
    }

    // Correct DP needs ordered pair (prev, last).
    for (int s = 0; s < S; s++) {
        free(dp[s]);
    }
    free(dp);

    // dp2[mask][prevIndex][last]
    // prevIndex: 0 = home, 1..N = store index
    double ***dp2 = (double ***)malloc(sizeof(double **) * S);
    for (int s = 0; s < S; s++) {
        dp2[s] = (double **)malloc(sizeof(double *) * M);
        for (int pv = 0; pv < M; pv++) {
            dp2[s][pv] = (double *)malloc(sizeof(double) * M);
            for (int ls = 0; ls < M; ls++) dp2[s][pv][ls] = INF;
        }
    }

    // First visit i: path 0 -> i, state prev=0, last=i
    for (int i = 1; i <= N; i++) {
        dp2[1 << (i - 1)][0][i] = dist_angle(0.0, ang[0][i]);
    }

    for (int mask = 0; mask < S; mask++) {
        for (int prev = 0; prev < M; prev++) {
            for (int last = 1; last <= N; last++) {
                double cur = dp2[mask][prev][last];
                if (cur >= INF / 2) continue;
                if (!(mask & (1 << (last - 1)))) continue;
                if (prev == last) continue;

                // Current facing at 'last' is direction from prev to last
                double inAngle = ang[prev][last];

                for (int nxt = 1; nxt <= N; nxt++) {
                    if (mask & (1 << (nxt - 1))) continue;
                    double outAngle = ang[last][nxt];
                    double cost = cur + dist_angle(inAngle, outAngle);
                    int nmask = mask | (1 << (nxt - 1));
                    if (cost < dp2[nmask][last][nxt]) {
                        dp2[nmask][last][nxt] = cost;
                    }
                }
            }
        }
    }

    double ans = INF;
    int full = S - 1;
    for (int prev = 0; prev < M; prev++) {
        for (int last = 1; last <= N; last++) {
            double cur = dp2[full][prev][last];
            if (cur >= INF / 2) continue;
            if (prev == last) continue;
            double inAngle = ang[prev][last];
            double backAngle = ang[last][0];
            double total = cur + dist_angle(inAngle, backAngle);
            if (total < ans) ans = total;
        }
    }

    printf("%.10f\n", ans);

    for (int s = 0; s < S; s++) {
        for (int pv = 0; pv < M; pv++) free(dp2[s][pv]);
        free(dp2[s]);
    }
    free(dp2);

    for (int i = 0; i < M; i++) free(ang[i]);
    free(ang);
    free(p);

    return 0;
}

